// ---------------------------------------------------------------------------
// TINGPU register offsets, for the SDK and the standalone builds
//
// Generated by tools/refactor/gen_regs_wrap.py - do not edit by hand.
//
// tn_gpu_regs.h includes this header, so driver code only has to include
// tn_gpu_regs.h to name a register:
//
//   tn_hw_reg_set(TINGPU_INTEN, TINGPU_INTEN_CCDMA_EVENT_EN(1));
//
// TINGPU_<REG> is the byte offset of <REG> in the register block, in both
// builds. That is the spelling the hardware consumes: tn_hw_reg_set() adds it
// to TIN_GPU_BASE, and the CCDMA command buffers store it in memory for the
// command processor to walk, so the same macro serves an MMIO access and a
// command buffer entry. Only where the number comes from differs:
//
//   TN_MCUXSDK_BUILD    offsetof(TINGPU_Type, INTEN)
//                       PERI_TINGPU.h is on the include path, pulled in by
//                       fsl_device_registers.h, so the CMSIS struct is the
//                       single source of truth
//
//   standalone          TIN_GPU_INTEN
//                       PERI_TINGPU.h needs a CPU_MIMXRT* define and the CMSIS
//                       core headers and so cannot be included; the offsets
//                       come straight from the tin_gpu_regs.h table
//
// Because the SDK branch is derived with offsetof rather than restating the
// numbers, the two branches cannot drift: if the SDK header moves a register,
// the offset moves with it.
//
// The names are prefixed on purpose. The register aliases used to be published
// bare, which turned INTEN, VERID, STS0 and the rest into object-like macros
// over the global namespace and broke any struct member of the same name -
// FLEXSPI base->STS0 and SEMC->INTR both occur in the vglite test BSPs. With
// the prefix a translation unit may also use the CMSIS struct form and these
// offsets at the same time, which the bare names forbade.
//
// An array register keeps the numbered spelling of the offset table,
// TINGPU_COLOR_LUT3, and resolves to the element the CMSIS header declares,
// COLOR_LUT[3].
//
// Each register is stated once, in a form both branches can consume:
// TINGPU_REG(VERID) and TINGPU_REG_ARR(COLOR_LUT, 3).
//
// The field macros are the other half of the dialect. An SDK build takes the
// mask, the shift and the functional form of every field from PERI_TINGPU.h,
// so the list at the end of this header is compiled only in a standalone
// build, where the mask and the shift come from the offset table through
// TINGPU_REG, the same macro the offsets use, and the TINGPU_<REG>_<FLD>(x)
// builder the table lacks is supplied.
//
// Nothing here expands to an unprefixed name, so this header needs only the
// TIN_GPU_* names of the table.
//
// struct TINGPU_Type is the whole of what this header publishes. A register the
// offset table defines but the struct does not declare is not part of this
// version's register block, so nothing is stated for it here - no offset, no
// field macro, no index helper - and naming one is an undeclared-identifier
// error in either build rather than a name that resolves in one and not the
// other.
//
// Census
//    389 registers,  367 of them members of struct TINGPU_Type
//     22 present only in the offset table, so left out entirely
//     14 array registers with _IDX and _NUM helpers
//      0 numbered register tables given the same helpers, spelled out
//        member by member by the CMSIS header rather than as a C array
//    197 field mask and shift pairs, each value checked against
//        PERI_TINGPU.h, with the functional form the table lacks
// ---------------------------------------------------------------------------

#pragma once

#include "tn_types.h"

#if defined(TN_MCUXSDK_BUILD)

    #include <stddef.h>

// fsl_device_registers.h, which tn_gpu_regs.h includes ahead of this header,
// brings in PERI_TINGPU.h and with it struct TINGPU_Type. A scalar register is
// a plain member, an array register one of its elements.
    #define TINGPU_REG(_reg)            \
        ((tn_u32)offsetof(TINGPU_Type, _reg))
    #define TINGPU_REG_ARR(_reg, _idx)  \
        ((tn_u32)offsetof(TINGPU_Type, _reg[_idx]))

#else

// tn_gpu_regs.h includes tin_gpu_regs.h ahead of this header, so the TIN_GPU_<REG>
// offsets are in scope. The register name is pasted onto the prefix, which is
// why an array element is spelled with its index glued on, TIN_GPU_COLOR_LUT3:
// that is the name the offset table defines.
    #define TINGPU_REG(_reg)            \
        ((tn_u32)(TIN_GPU_ ## _reg))
    #define TINGPU_REG_ARR(_reg, _idx)  \
        ((tn_u32)(TIN_GPU_ ## _reg ## _idx))

#endif


