// ---------------------------------------------------------------------------
// Array register helpers
//
// Index form of the array registers, for driver loops. TINGPU_<NAME>_IDX(i) is
// the offset of element i and is equivalent to TINGPU_<NAME>i. The elements are
// contiguous 32-bit registers, so the stride is 4 bytes.
// ---------------------------------------------------------------------------

// TINGPU_Type::COLOR_LUT[256], 0x0100..0x04FC
#define TINGPU_COLOR_LUT_IDX(i)                  (TINGPU_COLOR_LUT0 + (4u * (i)))
#define TINGPU_COLOR_LUT_NUM                     256u
// TINGPU_Type::DST_ADDR[4], 0x0514..0x0520
#define TINGPU_DST_ADDR_IDX(i)                   (TINGPU_DST_ADDR0 + (4u * (i)))
#define TINGPU_DST_ADDR_NUM                      4u
// TINGPU_Type::DST_STRIDE[4], 0x0524..0x0530
#define TINGPU_DST_STRIDE_IDX(i)                 (TINGPU_DST_STRIDE0 + (4u * (i)))
#define TINGPU_DST_STRIDE_NUM                    4u
// TINGPU_Type::S1_ADDR[4], 0x0568..0x0574
#define TINGPU_S1_ADDR_IDX(i)                    (TINGPU_S1_ADDR0 + (4u * (i)))
#define TINGPU_S1_ADDR_NUM                       4u
// TINGPU_Type::S1_STRIDE[4], 0x0578..0x0584
#define TINGPU_S1_STRIDE_IDX(i)                  (TINGPU_S1_STRIDE0 + (4u * (i)))
#define TINGPU_S1_STRIDE_NUM                     4u
// TINGPU_Type::S1_CLRKEY_LOW[4], 0x0598..0x05A4
#define TINGPU_S1_CLRKEY_LOW_IDX(i)              (TINGPU_S1_CLRKEY_LOW0 + (4u * (i)))
#define TINGPU_S1_CLRKEY_LOW_NUM                 4u
// TINGPU_Type::S1_CLRKEY_HIGH[4], 0x05A8..0x05B4
#define TINGPU_S1_CLRKEY_HIGH_IDX(i)             (TINGPU_S1_CLRKEY_HIGH0 + (4u * (i)))
#define TINGPU_S1_CLRKEY_HIGH_NUM                4u
// TINGPU_Type::S2_ADDR[4], 0x05D4..0x05E0
#define TINGPU_S2_ADDR_IDX(i)                    (TINGPU_S2_ADDR0 + (4u * (i)))
